-- =====================================================================
-- PROJECT 22 — SPACED REPETITION SCHEDULER
-- =====================================================================
-- Una sola tabla con TODOS los temas del curso (sin separación por
-- CULT SMART 1 / 2 / 3: da igual el nivel, solo importan las fechas).
--
-- El contrato es el Excel public/assets/31-10-26.xlsx:
-- cada tema tiene su lista exacta de fechas de repaso, columna a columna,
-- donde cada columna acumula los días de su cabecera (+1, +4, +7, ...).
-- Esas fechas (2023 - 2033) viven en la columna fechas[]: ya NO se
-- recalculan desde el día en que ejecutas el script.
-- proxima_fecha es GENERATED: siempre es fechas[streak + 1], la columna
-- siguiente del Excel a la que vas.
--
-- - Lectura pública (visitas).
-- - Marcar "Repasado" SOLO con tu password especial (validado en
--   Postgres, nunca en el cliente): avanza al SIGUIENTE date del Excel.
-- - Temas nuevos que agregues a mano arrancan hoy y usan la escala
--   acumulada del CULT SMART 1 como referencia.
-- ⚠️ Recuerda cambiar tu password en scheduler_secret() ANTES de ejecutar.
-- ⚠️ Re-ejecutar el script borra tu progreso y resetea la racha a 0
--    (proxima_fecha vuelve a ser la primera columna del Excel).

-- =====================================================================
-- 0) LIMPIEZA (idempotente: puedes re-ejecutar este script las veces
--    que quieras; borra lo anterior de este proyecto y lo crea todo de
--    nuevo, incluida la versión vieja del schema)
-- =====================================================================
drop table if exists project_22_scheduler cascade;
drop function if exists scheduler_add_topic(text, text);
drop function if exists scheduler_add_topic(smallint, text, text);
drop function if exists scheduler_mark_reviewed(uuid, text);
drop function if exists scheduler_ladder();
drop function if exists scheduler_secret();

create extension if not exists "pgcrypto";

-- =====================================================================
-- 1) TU PASSWORD
-- =====================================================================
-- ⚠️ EDITA ESTA LÍNEA antes de ejecutar: escribe tu password entre comillas.
create or replace function scheduler_secret()
returns text
language sql
immutable
as $$
  select 'EDIT-ME-CHANGE-THIS-PASSWORD';
$$;

-- Nadie puede leer la función directamente: solo las RPC de abajo la usan.
revoke all on function scheduler_secret() from public, anon, authenticated;

-- =====================================================================
-- 2) LA ÚNICA TABLA
-- =====================================================================
create table project_22_scheduler (
  id uuid primary key default gen_random_uuid(),
  orden int not null,           -- orden del tema en el Excel
  tema text not null unique,
  streak int not null default 0, -- repasos ya hechos (0 = aún ninguno)
  fechas date[] not null,        -- TODAS las fechas de repaso del tema (del Excel)
  proxima_fecha date generated always as ( -- = fechas[streak + 1]
    fechas[least(streak + 1, coalesce(array_length(fechas, 1), 1))]
  ) stored,
  created_at timestamptz not null default now()
);

alter table project_22_scheduler enable row level security;

-- Lectura pública (anónimo y autenticados pueden ver el scheduler)
create policy "public read scheduler"
on project_22_scheduler
for select
to anon, authenticated
using (true);

-- Escritura: SOLO a través de las RPC con password (ninguna policy INSERT/UPDATE).
grant select on project_22_scheduler to anon, authenticated;

-- =====================================================================
-- 3) RPC: MARCAR TEMA COMO REPASADO (requiere password)
-- =====================================================================
-- Avanza al siguiente repaso del Excel: streak + 1 ⇒ proxima_fecha pasa
-- a ser fechas[streak + 2] (la columna siguiente, calculada automáticamente).
-- Nada de recalcular desde hoy: la agenda es la del Excel, pase lo que pase.
create or replace function scheduler_mark_reviewed(
  p_id uuid,
  p_pass text
)
returns project_22_scheduler
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row   project_22_scheduler;
  v_total int;
begin
  if p_pass is null or p_pass <> scheduler_secret() then
    raise exception 'WRONG_PASSWORD' using errcode = '42501';
  end if;

  select * into v_row from project_22_scheduler where id = p_id;

  if v_row.id is null then
    raise exception 'TOPIC_NOT_FOUND' using errcode = '22023';
  end if;

  v_total := coalesce(array_length(v_row.fechas, 1), 0);

  if v_row.streak >= v_total then
    raise exception 'ALL_REVIEWED' using errcode = '22023';
  end if;

  update project_22_scheduler
     set streak = v_row.streak + 1
   where id = p_id
  returning * into v_row;

  return v_row;
end;
$$;

revoke all on function scheduler_mark_reviewed(uuid, text) from public;
grant execute on function scheduler_mark_reviewed(uuid, text) to anon, authenticated;

-- =====================================================================
-- 4) RPC: AGREGAR TEMA (requiere password)
-- =====================================================================
-- Los temas del Excel nacen con sus fechas del seed de abajo; los que
-- agregues vos a mano arrancan HOY y acumulan la escala del CULT SMART 1.
create or replace function scheduler_add_topic(
  p_tema text,
  p_pass text
)
returns project_22_scheduler
language plpgsql
security definer
set search_path = public
as $$
declare
  v_orden  int;
  v_row    project_22_scheduler;
  v_inc    int[] := array[1, 4, 7, 9, 10,
                           1, 4, 7, 9, 10,
                           1, 4, 7, 9, 10,
                           12, 16, 21, 28, 30, 28, 30, 12, 28, 50, 60, 90,
                           120, 80, 100, 120, 140, 150, 250];
  v_fechas date[] := array[current_date];
  v_acum   int := 0;
begin
  if p_pass is null or p_pass <> scheduler_secret() then
    raise exception 'WRONG_PASSWORD' using errcode = '42501';
  end if;

  if p_tema is null or length(trim(p_tema)) = 0 then
    raise exception 'EMPTY_TOPIC' using errcode = '22023';
  end if;

  for i in 1..coalesce(array_length(v_inc, 1), 0) loop
    v_acum := v_acum + v_inc[i];
    v_fechas := v_fechas || (current_date + v_acum)::date;
  end loop;

  select coalesce(max(orden), 0) + 1 into v_orden from project_22_scheduler;

  values (v_orden, trim(p_tema), 0, v_fechas)
  returning * into v_row;

  return v_row;
end;
$$;

revoke all on function scheduler_add_topic(text, text) from public;
grant execute on function scheduler_add_topic(text, text) to anon, authenticated;

-- =====================================================================
-- 5) SEED: LOS 226 TEMAS DEL EXCEL CON SUS FECHAS EXACTAS
-- =====================================================================
-- Cada fila = (orden, tema, streak, fechas). Las fechas son literales copiadas
-- de public/assets/31-10-26.xlsx (hojas CULT SMART 1 / 2 / 3).
-- proxima_fecha no se inserta: la calcula la columna GENERATED (fechas[1]).
